From ff64c5bfef12461df8450e0f50bb693b5269c720 Mon Sep 17 00:00:00 2001
From: Ren Wei <n05ec@lzu.edu.cn>
Date: Fri, 3 Apr 2026 23:52:52 +0800
Subject: [PATCH] netfilter: xt_multiport: validate range encoding in
 checkentry

ports_match_v1() treats any non-zero pflags entry as the start of a
port range and unconditionally consumes the next ports[] element as
the range end.

The checkentry path currently validates protocol, flags and count, but
it does not validate the range encoding itself. As a result, malformed
rules can mark the last slot as a range start or place two range starts
back to back, leaving ports_match_v1() to step past the last valid
ports[] element while interpreting the rule.

Reject malformed multiport v1 rules in checkentry by validating that
each range start has a following element and that the following element
is not itself marked as another range start.

Fixes: a89ecb6a2ef7 ("[NETFILTER]: x_tables: unify IPv4/IPv6 multiport match")
Reported-by: Yifan Wu <yifanwucs@gmail.com>
Reported-by: Juefei Pu <tomapufckgml@gmail.com>
Co-developed-by: Yuan Tan <yuantan098@gmail.com>
Signed-off-by: Yuan Tan <yuantan098@gmail.com>
Suggested-by: Xin Liu <bird@lzu.edu.cn>
Tested-by: Yuhang Zheng <z1652074432@gmail.com>
Signed-off-by: Ren Wei <n05ec@lzu.edu.cn>
Signed-off-by: Florian Westphal <fw@strlen.de>

diff --git a/net/netfilter/xt_multiport.c b/net/netfilter/xt_multiport.c
index 44a00f5acde8..a1691ff405d3 100644
--- a/net/netfilter/xt_multiport.c
+++ b/net/netfilter/xt_multiport.c
@@ -105,6 +105,28 @@ multiport_mt(const struct sk_buff *skb, struct xt_action_param *par)
 	return ports_match_v1(multiinfo, ntohs(pptr[0]), ntohs(pptr[1]));
 }

+static bool
+multiport_valid_ranges(const struct xt_multiport_v1 *multiinfo)
+{
+	unsigned int i;
+
+	for (i = 0; i < multiinfo->count; i++) {
+		if (!multiinfo->pflags[i])
+			continue;
+
+		if (++i >= multiinfo->count)
+			return false;
+
+		if (multiinfo->pflags[i])
+			return false;
+
+		if (multiinfo->ports[i - 1] > multiinfo->ports[i])
+			return false;
+	}
+
+	return true;
+}
+
 static inline bool
 check(u_int16_t proto,
       u_int8_t ip_invflags,
@@ -127,8 +149,10 @@ static int multiport_mt_check(const struct xt_mtchk_param *par)
 	const struct ipt_ip *ip = par->entryinfo;
 	const struct xt_multiport_v1 *multiinfo = par->matchinfo;

-	return check(ip->proto, ip->invflags, multiinfo->flags,
-		     multiinfo->count) ? 0 : -EINVAL;
+	if (!check(ip->proto, ip->invflags, multiinfo->flags, multiinfo->count))
+		return -EINVAL;
+
+	return multiport_valid_ranges(multiinfo) ? 0 : -EINVAL;
 }

 static int multiport_mt6_check(const struct xt_mtchk_param *par)
@@ -136,8 +160,10 @@ static int multiport_mt6_check(const struct xt_mtchk_param *par)
 	const struct ip6t_ip6 *ip = par->entryinfo;
 	const struct xt_multiport_v1 *multiinfo = par->matchinfo;

-	return check(ip->proto, ip->invflags, multiinfo->flags,
-		     multiinfo->count) ? 0 : -EINVAL;
+	if (!check(ip->proto, ip->invflags, multiinfo->flags, multiinfo->count))
+		return -EINVAL;
+
+	return multiport_valid_ranges(multiinfo) ? 0 : -EINVAL;
 }

 static struct xt_match multiport_mt_reg[] __read_mostly = {
-- 
2.34.1

The code statements that lead to the bug are:
return check(ip->proto, ip->invflags, multiinfo->flags,
	     multiinfo->count) ? 0 : -EINVAL;
return check(ip->proto, ip->invflags, multiinfo->flags,
	     multiinfo->count) ? 0 : -EINVAL;
Reason:
The original `multiport_mt_check` and `multiport_mt6_check` only validated protocol, flags, and count via the `check` function. They did not validate the range encoding in the `pflags` and `ports` arrays. This allowed malformed rules where a non-zero `pflags` entry (indicating a range start) could be placed in the last slot without a following element, or two range starts could appear consecutively. Consequently, `ports_match_v1()` could read beyond the valid `ports[]` array, causing out-of-bounds access and potential crashes or security issues.

The code statements that fix the bug are:
if (!multiinfo->pflags[i])
	continue;
if (++i >= multiinfo->count)
	return false;
if (multiinfo->pflags[i])
	return false;
if (multiinfo->ports[i - 1] > multiinfo->ports[i])
	return false;
if (!check(ip->proto, ip->invflags, multiinfo->flags, multiinfo->count))
	return -EINVAL;
return multiport_valid_ranges(multiinfo) ? 0 : -EINVAL;
if (!check(ip->proto, ip->invflags, multiinfo->flags, multiinfo->count))
	return -EINVAL;
return multiport_valid_ranges(multiinfo) ? 0 : -EINVAL;
Reason:
The new `multiport_valid_ranges` function iterates over the `pflags` and `ports` arrays. For each non-zero `pflags` entry (range start), it ensures that there is a following element, that the following element is not itself a range start, and that the range is ordered (start port <= end port). This validation prevents malformed rules from being accepted. The validation is integrated into both `multiport_mt_check` and `multiport_mt6_check` by first calling the original `check` function and then calling `multiport_valid_ranges`. Only if both checks pass is the rule considered valid, thus eliminating the vulnerability.

